    <script>
        function addDeparture(){const p=document.getElementById('departures'),i=p.children.length;p.insertAdjacentHTML('beforeend',`<div class="grid gap-3 sm:grid-cols-[1fr_auto]"><input class="admin-input !mt-0" required type="time" name="departures[${i}][start_time]"><label class="flex items-center gap-2 text-sm font-semibold"><input type="hidden" name="departures[${i}][is_active]" value="0"><input type="checkbox" name="departures[${i}][is_active]" value="1" checked> Active</label></div>`);}
        function tripPriceSelects(){return [...document.querySelectorAll('#trip-prices select[name$="[vehicle_id]"]')];}
        function syncTripPrices(){const selects=tripPriceSelects(),used=selects.map(select=>select.value).filter(Boolean);selects.forEach(select=>select.querySelectorAll('option').forEach(option=>option.disabled=option.value!==select.value&&used.includes(option.value)));const button=document.getElementById('add-trip-price');if(button){const vehicleCount=selects[0]?.options.length??0,allUsed=selects.length>=vehicleCount;button.disabled=allUsed;button.classList.toggle('cursor-not-allowed',allUsed);button.classList.toggle('opacity-50',allUsed);}}
        function addTripPrice(){const list=document.getElementById('trip-prices'),template=document.getElementById('trip-price-template');if(!list||!template)return;const used=new Set(tripPriceSelects().map(select=>select.value).filter(Boolean)),fragment=template.content.cloneNode(true),select=fragment.querySelector('select'),nextVehicle=[...select.options].find(option=>!used.has(option.value));if(!nextVehicle)return;select.value=nextVehicle.value;const index=list.children.length;fragment.querySelectorAll('[data-price-name]').forEach(field=>{field.name=`prices[${index}][${field.dataset.priceName}]`;field.removeAttribute('data-price-name')});list.append(fragment);syncTripPrices();}

        function setupTripContentEditor(){const form=document.querySelector('[data-trip-rich-content-form]');if(!form)return;const editor=form.querySelector('[data-trip-rich-editor]'),html=form.querySelector('[data-trip-rich-html]'),toolbar=form.querySelector('[data-trip-editor-toolbar]'),status=form.querySelector('[data-trip-rich-status]');let savedRange=null;const sync=()=>html.value=editor.innerHTML.trim();const saveRange=()=>{const selection=window.getSelection();if(selection?.rangeCount&&editor.contains(selection.anchorNode))savedRange=selection.getRangeAt(0).cloneRange();};const restoreRange=()=>{editor.focus();if(!savedRange)return;const selection=window.getSelection();selection.removeAllRanges();selection.addRange(savedRange);};const placeCaret=node=>{const range=document.createRange(),selection=window.getSelection();range.selectNodeContents(node);range.collapse(false);selection.removeAllRanges();selection.addRange(range);savedRange=range.cloneRange();};const currentBlock=()=>{const selection=window.getSelection();let node=selection?.anchorNode;if(node?.nodeType===Node.TEXT_NODE)node=node.parentElement;while(node&&node!==editor){if(['p','div','h2','h3','h4','h5','blockquote','li'].includes(node.tagName.toLowerCase()))return node;node=node.parentElement;}return null;};const ensureBlock=()=>{const block=currentBlock();if(block)return block;const paragraph=document.createElement('p'),selection=window.getSelection(),range=selection?.rangeCount?selection.getRangeAt(0):null;if(range&&!range.collapsed){paragraph.append(range.extractContents());range.insertNode(paragraph);}else{paragraph.innerHTML='<br>';editor.append(paragraph);}return paragraph;};const applyBlock=tag=>{const source=ensureBlock();if(source.tagName.toLowerCase()===tag){placeCaret(source);return;}const replacement=document.createElement(tag);replacement.innerHTML=source.innerHTML||'<br>';source.replaceWith(replacement);placeCaret(replacement);};const applyList=tag=>{const source=ensureBlock();const list=document.createElement(tag),item=document.createElement('li');item.innerHTML=source.innerHTML||'<br>';list.append(item);source.replaceWith(list);placeCaret(item);};toolbar.addEventListener('mousedown',event=>event.preventDefault());toolbar.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;restoreRange();const command=button.dataset.editorCommand;if(button.dataset.editorBlock)applyBlock(button.dataset.editorBlock);else if(command==='insertUnorderedList')applyList('ul');else if(command==='insertOrderedList')applyList('ol');else if(command)document.execCommand(command,false,null);if(button.hasAttribute('data-editor-link')){const url=window.prompt('Link URL (https://, mailto:, tel: or /):');if(url){restoreRange();document.execCommand('createLink',false,url);}}saveRange();sync();status.textContent='Formatting will be saved with your content.';});editor.addEventListener('mouseup',saveRange);editor.addEventListener('keyup',saveRange);editor.addEventListener('input',()=>{saveRange();sync();});form.addEventListener('submit',sync);sync();}

